insert.foreach:
INSERT INTO TB_MTNG_PTCPT (
    MTNG_PTCPT_ID,
    MTNG_ID,
    EMP_ID
) VALUES (
    SEQ_MTNG_PTCPT_ID.NEXTVAL,
    #{ptcpt.mtngId},
    #{ptcpt.empId}
)

mapper.update:
UPDATE TB_MTNG
SET CONF_RM_RSRV_ID = #{confRmRsrvId}
WHERE MTNG_ID = #{mtngId}

mapper.select:
SELECT * FROM ( SELECT M.MTNG_ID, M.MTNG_NM, M.MTNG_TYPE_CD, M.BEGIN_DT, M.END_DT, M.CRTR_ID, E.EMP_NM AS CRTR_NM, V.VCONF_ID, V.ROOM_NM, MM.MOM_STTUS_CD, ( SELECT COUNT(*) FROM TB_MTNG_PTCPT P WHERE P.MTNG_ID = M.MTNG_ID ) AS PTCPT_CNT FROM TB_MTNG M INNER JOIN TB_MTNG_PTCPT MP ON MP.MTNG_ID = M.MTNG_ID AND MP.EMP_ID = #{empId} LEFT JOIN TB_EMPLOYEE E ON E.EMP_ID = M.CRTR_ID LEFT JOIN TB_VIDEO_CONF V ON V.MTNG_ID = M.MTNG_ID LEFT JOIN TB_MTNG_MOM MM ON MM.MOM_ID = ( SELECT MAX(MOM_ID) FROM TB_MTNG_MOM WHERE MTNG_ID = M.MTNG_ID AND DEL_DT IS NULL ) LEFT JOIN TB_CONF_RM_RSRV R ON R.RSRV_ID = M.CONF_RM_RSRV_ID LEFT JOIN TB_CONF_RM CR ON CR.CONF_RM_ID = R.CONF_RM_ID WHERE M.DEL_YN = 'N'
AND M.END_DT >= #{beginDt}
AND M.BEGIN_DT <= #{endDt}
AND ( M.MTNG_NM LIKE '%' || #{keyword} || '%' OR MM.MOM_CN LIKE '%' || #{keyword} || '%' OR EXISTS ( SELECT 1 FROM TB_MTNG_PTCPT KP INNER JOIN TB_EMPLOYEE KE ON KE.EMP_ID = KP.EMP_ID WHERE KP.MTNG_ID = M.MTNG_ID AND KE.EMP_NM LIKE '%' || #{keyword} || '%' ) )
ORDER BY M.BEGIN_DT ASC )
WHERE ROWNUM <= #{limit}

mapper.update:
UPDATE TB_MTNG
SET DEL_YN = 'Y'
WHERE MTNG_ID = #{mtngId}

mapper.select:
SELECT BEGIN_DT
FROM TB_MTNG
WHERE MTNG_ID = #{mtngId}

SELECT VCONF_ID, MTNG_ID, ROOM_NM, VCONF_NM, CRTR_ID, CREAT_DT
FROM TB_VIDEO_CONF
WHERE MTNG_ID = #{mtngId}
